def parse_body(data) when byte_size(data) < 15 do
  {:error, :not_enough_data}
end
def parse_body(<<_head::40, data_size::24, _rest::binary>> = data)
    when byte_size(data) < data_size + 15 do
  {:error, :not_enough_data}
end
def parse_body(
      <<_head::32, _reserved::2, 0::1, 18::5, data_size::24, _timestamp::24,
        _timestamp_extended::8, _stream_id::24, _payload::binary-size(data_size), rest::binary>>
    ) do
  parse_body(rest)
end
def parse_body(
      <<_previous_tag_size::32, _reserved::2, 0::1, type::5, data_size::24, timestamp::24,
        timestamp_extended::8, stream_id::24, payload::binary-size(data_size), rest::binary>>
    ) do
  type = resolve_type(type)

  with {:ok, {type, codec, codec_params, payload}} <- parse_payload(type, payload) do
    dts = parse_timestamp(timestamp, timestamp_extended)
    pts = dts + Map.get(codec_params, :composition_time, 0)

    packet = %Packet{
      pts: pts,
      dts: dts,
      stream_id: stream_id,
      type: type,
      payload: payload,
      codec: codec,
      codec_params: codec_params
    }

    case parse_body(rest) do
      {:ok, packets, rest} -> {:ok, [packet | packets], rest}
      {:error, :not_enough_data} -> {:ok, [packet], rest}
    end
  end
end
def parse_body(_too_little_data) do
  {:error, :not_enough_data}
end

def parse_header(
      <<"FLV", 1::8, 0::5, type_flags_audio::1, 0::1, type_flags_video::1, data_offset::32,
        _body::binary>> = data
    ) do
  case data do
    <<_header::binary-size(data_offset), rest::binary>> ->
      %Header{audio_present?: type_flags_audio == 1, video_present?: type_flags_video == 1}
      |> then(&{:ok, &1, rest})

    _else ->
      {:error, :not_enough_data}
  end
end
def parse_header(data) when byte_size(data) < 9 do
  {:error, :not_enough_data}
end
def parse_header(_incorrect_data) do
  {:error, :not_a_header}
end

